/**
 * Dashboard read vocabulary — section schemas composed by GetDashboard.
 * Generic atoms (Metric/CurrencyMetric/Tally/segmented) come from @shared/schemas.
 */
import { z } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	CostKind,
	MarketingPlatform,
	AdAttribution,
	DisputeStatus,
	PaymentMethod,
	PaymentStatus,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MetricSchema, CurrencyMetricSchema, TallySchema, ConsolidatedTallySchema, segmented } from '../../shared/schemas'

// ---------------------------------------------------------------------------
// Segmented breakdowns (mono-currency)
// ---------------------------------------------------------------------------
export const CostBreakdownSchema = segmented(CostKind)
export const AdsByPlatformSchema = segmented(MarketingPlatform)
export const AdsByTypeSchema = segmented(AdAttribution)
export const ChargebackByStatusSchema = segmented(DisputeStatus)

// ---------------------------------------------------------------------------
// Named breakdowns (tooltip data — mono-currency)
// ---------------------------------------------------------------------------
export const FeesBreakdownSchema = z.object({
	gateway: MetricSchema,
	checkout: MetricSchema,
	chargeback: MetricSchema,
})

export const AdsBreakdownSchema = z.object({
	total: MetricSchema,
	byPlatform: AdsByPlatformSchema,
	byType: AdsByTypeSchema,
	tax: MetricSchema,
	cpa: MetricSchema,
	roi: MetricSchema,
	roas: MetricSchema,
})

export const ChargebackBreakdownSchema = z.object({
	byStatus: ChargebackByStatusSchema,
	fees: MetricSchema,
})

export const TaxesBreakdownSchema = z.object({
	ads: MetricSchema,
	others: MetricSchema,
})

export const ProductCostBreakdownSchema = z.object({
	product: MetricSchema,
	shipping: MetricSchema,
})

// ---------------------------------------------------------------------------
// Consolidated breakdown variants (money leaves → CurrencyMetric; ratios stay Metric)
// ---------------------------------------------------------------------------
export const ConsolidatedFeesBreakdownSchema = z.object({
	gateway: CurrencyMetricSchema,
	checkout: CurrencyMetricSchema,
	chargeback: CurrencyMetricSchema,
})

export const ConsolidatedAdsBreakdownSchema = z.object({
	total: CurrencyMetricSchema,
	byPlatform: z.object({
		total: CurrencyMetricSchema,
		segments: z.enumRecord(MarketingPlatform, CurrencyMetricSchema),
	}),
	byType: z.object({
		total: CurrencyMetricSchema,
		segments: z.enumRecord(AdAttribution, CurrencyMetricSchema),
	}),
	tax: CurrencyMetricSchema,
	cpa: MetricSchema,
	roi: MetricSchema,
	roas: MetricSchema,
})

export const ConsolidatedProductCostBreakdownSchema = z.object({
	product: CurrencyMetricSchema,
	shipping: CurrencyMetricSchema,
})

export const ConsolidatedChargebackBreakdownSchema = z.object({
	byStatus: z.object({
		total: CurrencyMetricSchema,
		segments: z.enumRecord(DisputeStatus, CurrencyMetricSchema),
	}),
	fees: CurrencyMetricSchema,
})

export const ConsolidatedTaxesBreakdownSchema = z.object({
	ads: CurrencyMetricSchema,
	others: CurrencyMetricSchema,
})

// ---------------------------------------------------------------------------
// Operational costs
// ---------------------------------------------------------------------------
export const OperationalCostItemSchema = z.object({
	id: z.string(),
	name: z.string(),
	flow: z.enum(OperationalCostFlow),
	frequency: z.enum(OperationalCostRecurrency),
	amount: z.number(),
	currency: z.enum(CurrencyCode),
	startDate: z.iso.datetime({ offset: true }),
	endDate: z.iso.datetime({ offset: true }).nullable(),
})

export const OperationalCostsSchema = z.object({
	total: MetricSchema,
	items: z.array(OperationalCostItemSchema),
})

export const ConsolidatedOperationalCostsSchema = z.object({
	total: CurrencyMetricSchema,
	items: z.array(OperationalCostItemSchema),
})

// ---------------------------------------------------------------------------
// Stat (StatCards region) — orders lives in details, not here
// ---------------------------------------------------------------------------
export const StatSchema = z.object({
	revenue: MetricSchema,
	profit: MetricSchema,
	margin: MetricSchema,
	averageTicket: MetricSchema,
	unitsSold: MetricSchema,
	costs: CostBreakdownSchema,
})

/** Per-store Stat keyed by StoreIntegrationId (UUID string). Each store mono-currency. */
export const PerStoreStatSchema = z.record(z.string(), StatSchema)

export const CurrencyCostBreakdownSchema = z.object({
	total: CurrencyMetricSchema,
	segments: z.enumRecord(CostKind, CurrencyMetricSchema),
})

export const ConsolidatedStatSchema = z.object({
	revenue: CurrencyMetricSchema,
	profit: CurrencyMetricSchema,
	margin: MetricSchema,
	averageTicket: CurrencyMetricSchema,
	unitsSold: MetricSchema,
	costs: CurrencyCostBreakdownSchema,
})

// ---------------------------------------------------------------------------
// Orders summary (lives inside details)
// ---------------------------------------------------------------------------
export const OrdersSummarySchema = z.object({
	generated: TallySchema,
	paid: TallySchema,
})

export const ConsolidatedOrdersSummarySchema = z.object({
	generated: ConsolidatedTallySchema,
	paid: ConsolidatedTallySchema,
})

// ---------------------------------------------------------------------------
// Payment method breakdown (NATIONAL mode only) — total → byMethod → byStatus
// ---------------------------------------------------------------------------
export const PaymentMethodBreakdownSchema = z.object({
	total: TallySchema,
	byMethod: z.enumRecord(
		PaymentMethod,
		z.object({
			total: TallySchema,
			byStatus: z.enumRecord(PaymentStatus, TallySchema),
		}),
	),
})

// ---------------------------------------------------------------------------
// Dashboard details (orders + cost/fee/tax breakdowns)
// ---------------------------------------------------------------------------
export const DashboardDetailsSchema = z.object({
	orders: OrdersSummarySchema,
	fees: FeesBreakdownSchema,
	ads: AdsBreakdownSchema,
	productCost: ProductCostBreakdownSchema,
	chargeback: ChargebackBreakdownSchema,
	refund: MetricSchema,
	taxes: TaxesBreakdownSchema,
	operational: OperationalCostsSchema,
})

export const ConsolidatedDashboardDetailsSchema = z.object({
	orders: ConsolidatedOrdersSummarySchema,
	fees: ConsolidatedFeesBreakdownSchema,
	ads: ConsolidatedAdsBreakdownSchema,
	productCost: ConsolidatedProductCostBreakdownSchema,
	chargeback: ConsolidatedChargebackBreakdownSchema,
	refund: CurrencyMetricSchema,
	taxes: ConsolidatedTaxesBreakdownSchema,
	operational: ConsolidatedOperationalCostsSchema,
})

import { injectable } from 'tsyringe-neo'
import Z from 'zod'
import { Handler, z } from '@bk-dash/core-typescript'
import {
	TenancyScope,
	DashboardMode,
	CurrencyCode,
	CostKind,
	MarketingPlatform,
	AdAttribution,
	DisputeStatus,
	PaymentMethod,
	PaymentStatus,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MetricSchema, CurrencyMetricSchema, CurrencyAmountSchema, TallySchema, ConsolidatedTallySchema } from '../../shared/schemas'
import {
	StatSchema,
	ConsolidatedStatSchema,
	PerStoreStatSchema,
	DashboardDetailsSchema,
	ConsolidatedDashboardDetailsSchema,
	PaymentMethodBreakdownSchema,
	OperationalCostItemSchema,
} from '../schemas'
import { faker, mockId, mockMoney, mockMetric, mockSeries, pick } from '../../shared/testing/mock'
import { StoreVisualizationRepository } from '../repositories/StoreVisualizationRepository'

// ---------------------------------------------------------------------------
// Input — `tenancyScope` selects the store set; `dashboardMode` is NOT a query
// param (read from the persisted StoreVisualization). storeId/storeIds come
// from ctx. productIds is an optional filter.
// ---------------------------------------------------------------------------
export const GetDashboardInputSchema = z.object({
	tenancyScope: z.enum(TenancyScope),
	storeId: z.uuid(), // ← ctx.session.storeId      (SINGLE_STORE)
	storeIds: z.array(z.uuid()), // ← ctx.membership.storeIds  (MULTI_STORE)
	startDate: z.date(),
	endDate: z.date(),
	productIds: z.array(z.uuid()).optional(),
})

// ---------------------------------------------------------------------------
// Output — composition-first discriminated union. Section shape fragments +
// a `variant()` composer + a single `z.discriminatedUnion('kind', …)`.
// Both real enums are echoed for the frontend.
// ---------------------------------------------------------------------------
const STORE = { store: z.object({ id: z.uuid(), currency: z.enum(CurrencyCode) }) }
const STAT = { stat: StatSchema }
const STAT_CONSOLIDATED = { stat: ConsolidatedStatSchema, perStore: PerStoreStatSchema }
const DETAILS = { details: DashboardDetailsSchema }
const DETAILS_CONS = { details: ConsolidatedDashboardDetailsSchema }
const PAYMENT_METHODS = { paymentMethods: PaymentMethodBreakdownSchema }

const variant = (kind: string, tenancyScope: TenancyScope, dashboardMode: DashboardMode, ...shapes: Record<string, Z.ZodTypeAny>[]) =>
	z.object({
		kind: z.literal(kind),
		tenancyScope: z.literal(tenancyScope),
		dashboardMode: z.literal(dashboardMode),
		...Object.assign({}, ...shapes),
	})

const SINGLE_GLOBAL = variant('SINGLE_GLOBAL', TenancyScope.SINGLE_STORE, DashboardMode.GLOBAL, STORE, STAT, DETAILS)
const SINGLE_NATIONAL = variant('SINGLE_NATIONAL', TenancyScope.SINGLE_STORE, DashboardMode.NATIONAL, STORE, STAT, DETAILS, PAYMENT_METHODS)
const MULTI_GLOBAL = variant('MULTI_GLOBAL', TenancyScope.MULTI_STORE, DashboardMode.GLOBAL, STAT_CONSOLIDATED, DETAILS_CONS)
const MULTI_NATIONAL = variant(
	'MULTI_NATIONAL',
	TenancyScope.MULTI_STORE,
	DashboardMode.NATIONAL,
	STAT_CONSOLIDATED,
	DETAILS_CONS,
	PAYMENT_METHODS,
)

export const GetDashboardOutputSchema = z.discriminatedUnion('kind', [SINGLE_GLOBAL, SINGLE_NATIONAL, MULTI_GLOBAL, MULTI_NATIONAL])

// ---------------------------------------------------------------------------
// Faker builders (each typed by its schema so tsc verifies the shape).
// Swap the use-case body for a real cross-context aggregation later; the
// contract above is final.
// ---------------------------------------------------------------------------
type Metric = Z.infer<typeof MetricSchema>
type CurrencyMetric = Z.infer<typeof CurrencyMetricSchema>

const fakeMetric = (): Metric => mockMetric()
const fakeCurrencyAmount = (): Z.infer<typeof CurrencyAmountSchema> => {
	const currencies = faker.helpers.arrayElements(Object.values(CurrencyCode), 2)
	return Object.fromEntries(currencies.map(c => [c, mockMoney()]))
}
const fakeCurrencyMetric = (): CurrencyMetric => ({
	value: fakeCurrencyAmount(),
	deltaPct: faker.datatype.boolean() ? faker.number.float({ min: -1, max: 1, fractionDigits: 2 }) : null,
})

const recordOf = <T extends Record<string, string>, V>(enumObject: T, fn: () => V): Record<T[keyof T], V> =>
	Object.fromEntries(Object.values(enumObject).map(v => [v, fn()])) as Record<T[keyof T], V>

const segmentedMetric = <T extends Record<string, string>>(enumObject: T) => ({
	total: fakeMetric(),
	segments: recordOf(enumObject, fakeMetric),
})
const segmentedCurrency = <T extends Record<string, string>>(enumObject: T) => ({
	total: fakeCurrencyMetric(),
	segments: recordOf(enumObject, fakeCurrencyMetric),
})

const fakeTally = (): Z.infer<typeof TallySchema> => ({ count: fakeMetric(), value: fakeMetric() })
const fakeConsolidatedTally = (): Z.infer<typeof ConsolidatedTallySchema> => ({ count: fakeMetric(), value: fakeCurrencyMetric() })

const fakeOperationalItem = (): Z.infer<typeof OperationalCostItemSchema> => ({
	id: mockId(),
	name: faker.commerce.productName(),
	flow: pick(Object.values(OperationalCostFlow)),
	frequency: pick(Object.values(OperationalCostRecurrency)),
	amount: mockMoney(),
	currency: pick(Object.values(CurrencyCode)),
	startDate: faker.date.recent({ days: 30 }).toISOString(),
	endDate: null,
})

const fakeStat = (): Z.infer<typeof StatSchema> => ({
	revenue: fakeMetric(),
	profit: fakeMetric(),
	margin: fakeMetric(),
	averageTicket: fakeMetric(),
	unitsSold: fakeMetric(),
	costs: segmentedMetric(CostKind),
})

const fakeConsolidatedStat = (): Z.infer<typeof ConsolidatedStatSchema> => ({
	revenue: fakeCurrencyMetric(),
	profit: fakeCurrencyMetric(),
	margin: fakeMetric(),
	averageTicket: fakeCurrencyMetric(),
	unitsSold: fakeMetric(),
	costs: { total: fakeCurrencyMetric(), segments: recordOf(CostKind, fakeCurrencyMetric) },
})

const fakeDetails = (): Z.infer<typeof DashboardDetailsSchema> => ({
	orders: { generated: fakeTally(), paid: fakeTally() },
	fees: { gateway: fakeMetric(), checkout: fakeMetric(), chargeback: fakeMetric() },
	ads: {
		total: fakeMetric(),
		byPlatform: segmentedMetric(MarketingPlatform),
		byType: segmentedMetric(AdAttribution),
		tax: fakeMetric(),
		cpa: fakeMetric(),
		roi: fakeMetric(),
		roas: fakeMetric(),
	},
	productCost: { product: fakeMetric(), shipping: fakeMetric() },
	chargeback: { byStatus: segmentedMetric(DisputeStatus), fees: fakeMetric() },
	refund: fakeMetric(),
	taxes: { ads: fakeMetric(), others: fakeMetric() },
	operational: { total: fakeMetric(), items: mockSeries(3, fakeOperationalItem) },
})

const fakeConsolidatedDetails = (): Z.infer<typeof ConsolidatedDashboardDetailsSchema> => ({
	orders: { generated: fakeConsolidatedTally(), paid: fakeConsolidatedTally() },
	fees: { gateway: fakeCurrencyMetric(), checkout: fakeCurrencyMetric(), chargeback: fakeCurrencyMetric() },
	ads: {
		total: fakeCurrencyMetric(),
		byPlatform: segmentedCurrency(MarketingPlatform),
		byType: segmentedCurrency(AdAttribution),
		tax: fakeCurrencyMetric(),
		cpa: fakeMetric(),
		roi: fakeMetric(),
		roas: fakeMetric(),
	},
	productCost: { product: fakeCurrencyMetric(), shipping: fakeCurrencyMetric() },
	chargeback: { byStatus: segmentedCurrency(DisputeStatus), fees: fakeCurrencyMetric() },
	refund: fakeCurrencyMetric(),
	taxes: { ads: fakeCurrencyMetric(), others: fakeCurrencyMetric() },
	operational: { total: fakeCurrencyMetric(), items: mockSeries(3, fakeOperationalItem) },
})

const fakePaymentMethods = (): Z.infer<typeof PaymentMethodBreakdownSchema> => ({
	total: fakeTally(),
	byMethod: recordOf(PaymentMethod, () => ({ total: fakeTally(), byStatus: recordOf(PaymentStatus, fakeTally) })),
})

const fakePerStore = (storeIds: string[]): Z.infer<typeof PerStoreStatSchema> => Object.fromEntries(storeIds.map(id => [id, fakeStat()]))

/** Deterministic seed from the request so refetches return stable fixtures. */
const seedFrom = (parts: string[]): number => {
	const s = parts.join('|')
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

/**
 * `GetDashboard` — composition-first discriminated dashboard read.
 *
 * FAKER body, REAL contract: `tenancyScope` (query) selects SINGLE vs MULTI
 * store shape; `dashboardMode` is read from the persisted `StoreVisualization`
 * (default GLOBAL) and toggles the `paymentMethods` section. Real cross-context
 * aggregation is a later swap behind this interface.
 */
@injectable()
export class GetDashboard extends Handler<typeof GetDashboardInputSchema, typeof GetDashboardOutputSchema> {
	readonly name = 'get_dashboard' as const
	readonly inputSchema = GetDashboardInputSchema
	readonly outputSchema = GetDashboardOutputSchema

	constructor(private readonly visualizations: StoreVisualizationRepository) {
		super()
	}

	protected async handle(input: this['input']): Promise<this['output']> {
		faker.seed(seedFrom([input.storeId, input.startDate.toISOString(), input.endDate.toISOString(), ...(input.productIds ?? [])]))

		const visualization = await this.visualizations.findByStoreId(input.storeId)
		const dashboardMode = visualization?.dashboardMode ?? DashboardMode.GLOBAL
		const isMulti = input.tenancyScope === TenancyScope.MULTI_STORE
		const isNational = dashboardMode === DashboardMode.NATIONAL
		const kind = `${isMulti ? 'MULTI' : 'SINGLE'}_${dashboardMode}`

		const result = isMulti
			? {
					kind,
					tenancyScope: TenancyScope.MULTI_STORE,
					dashboardMode,
					stat: fakeConsolidatedStat(),
					perStore: fakePerStore(input.storeIds),
					details: fakeConsolidatedDetails(),
					...(isNational ? { paymentMethods: fakePaymentMethods() } : {}),
				}
			: {
					kind,
					tenancyScope: TenancyScope.SINGLE_STORE,
					dashboardMode,
					store: { id: input.storeId, currency: pick(Object.values(CurrencyCode)) },
					stat: fakeStat(),
					details: fakeDetails(),
					...(isNational ? { paymentMethods: fakePaymentMethods() } : {}),
				}

		return result as this['output']
	}
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { GetDashboard, GetDashboardInputSchema, GetDashboardOutputSchema } from '../usecases/GetDashboard'

export const GetDashboardControllerInputSchema = z.object({
	ctx: z.object({
		session: z.object({ storeId: z.uuid() }),
		membership: z.object({ storeIds: z.array(z.uuid()) }),
	}),
	query: GetDashboardInputSchema.omit({ storeId: true, storeIds: true, startDate: true, endDate: true, productIds: true }).extend({
		// Query params arrive as strings — coerce before the use case receives them.
		startDate: z.stringToDate(),
		endDate: z.stringToDate(),
		productIds: z.stringToArray(z.uuid()).optional(),
	}),
})

export const GetDashboardControllerOutputSchema = GetDashboardOutputSchema

@injectable()
export class GetDashboardController extends Controller<
	typeof GetDashboardControllerInputSchema,
	typeof GetDashboardControllerOutputSchema
> {
	readonly path = '/dashboard'
	readonly method = 'get' as const
	readonly description = 'Composition-first dashboard read — TenancyScope (query) × persisted DashboardMode'
	readonly inputSchema = GetDashboardControllerInputSchema
	readonly outputSchema = GetDashboardControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private query: GetDashboard) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.query.execute({
			tenancyScope: request.query.tenancyScope,
			storeId: request.ctx.session.storeId,
			storeIds: request.ctx.membership.storeIds,
			startDate: request.query.startDate,
			endDate: request.query.endDate,
			productIds: request.query.productIds,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

