import { PlusIcon } from '@/components/ui/icons'
import type { IconComponent } from '@/components/ui/icons'
import { cn } from '@/lib/utils'

interface AdditionalCostRowProps {
	icon: IconComponent
	label: string
	/** Pre-formatted display string — currency for `cost`, status text for `status`. */
	value: string
	valueKind: 'cost' | 'status'
	/** Whether the row exposes a "+" affordance to add an entry for this cost. */
	addable?: boolean
}

/**
 * One line of the Additional Costs card. Presentational leaf — the owning Section formats the
 * value and decides the variant. The "+" button is disabled pending the create flows
 * (operational cost / tax / warranty); see the spec's Open Questions.
 */
export function AdditionalCostRow({ icon: Icon, label, value, valueKind, addable }: AdditionalCostRowProps) {
	return (
		<div role="listitem" className="flex items-center gap-3">
			<Icon className="size-4 shrink-0 text-muted-foreground" />
			<span className="text-sm text-foreground">{label}</span>
			{addable ? (
				<Button
					size="icon-sm"
					className="rounded-full"
					disabled
					aria-label={`Adicionar ${label}`}
					title="Em breve"
				>
					<PlusIcon />
				</Button>
			) : null}
			<span className={cn('ml-auto text-sm font-medium', valueKind === 'cost' ? 'text-destructive' : 'text-success')}>
				{value}
			</span>
		</div>
	)
}

