import { createFileRoute } from '@tanstack/react-router'
import { endOfDay, startOfDay, subDays } from 'date-fns'
import { z } from 'zod'

import { RouteError } from '@/components/RouteError'
import { AdditionalCostsSection } from './-components/AdditionalCostsSection'

// Dashboard period + scope live in the URL so the view is bookmarkable. Defaults: last 30 days,
// single-store. The display preference (discount additional costs) is store state, not URL.
const searchSchema = z.object({
	tenancyScope: z.enum(['SINGLE_STORE', 'MULTI_STORE']).default('SINGLE_STORE'),
	startDate: z.string().default(() => startOfDay(subDays(new Date(), 29)).toISOString()),
	endDate: z.string().default(() => endOfDay(new Date()).toISOString()),
	productIds: z.array(z.string()).optional(),
})

export const Route = createFileRoute('/(app)/dashboard/')({
	validateSearch: search => searchSchema.parse(search ?? {}),
	component: RouteComponent,
	errorComponent: RouteError,
})

function RouteComponent() {
	return (
		<div className="p-8">
			<div className="max-w-md">
				<AdditionalCostsSection />
			</div>
		</div>
	)
}

