import { persist } from 'zustand/middleware'
import type { TenancyScope } from '@bk-dash/client-typescript/typescript'

/**
 * App-global tenancy scope — whether reads target a single store or the consolidated
 * multi-store view. Lives here (not in URL search) because it is an account-level mode shared by
 * every screen that queries store-scoped data, not a per-route, bookmarkable filter. Persisted so
 * the choice survives refresh.
 */
interface TenancyStore {
	tenancyScope: TenancyScope
	setTenancyScope: (scope: TenancyScope) => void
}

export const useTenancyStore = create<TenancyStore>()(
	persist(
		set => ({
			tenancyScope: 'SINGLE_STORE',
			setTenancyScope: scope => set({ tenancyScope: scope }),
		}),
		{ name: 'tenancy-storage' },
	),
)

