import { useMemo } from 'react'
import { getRouteApi } from '@tanstack/react-router'
import { useGetDashboard } from '@bk-dash/client-typescript/typescript'

import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { BalanceIcon, CardIcon, CashIcon, EngineIcon, LockIcon, RefundIcon } from '@/components/ui/icons'
import type { IconComponent } from '@/components/ui/icons'
import { formatCurrency } from '@/lib/format'
import { useTenancyStore } from '@/stores'

import { DiscountCostsToggle } from './DiscountCostsToggle'
import { AdditionalCostRow } from './AdditionalCostRow'

const routeApi = getRouteApi('/(app)/dashboard/')

interface CostRow {
	key: string
	icon: IconComponent
	label: string
	value: string
	valueKind: 'cost' | 'status'
	addable: boolean
}

/**
 * Additional Costs card — the period's chargeback / refund / taxes / operational costs read from
 * `GetDashboard`'s cost segments, plus a placeholder warranty row. Owns the dashboard query for
 * this region and feeds the rows by props. Consolidated (multi-store) currency display is not yet
 * defined (see spec OQ-2) — for now only mono-currency (SINGLE_STORE) renders the breakdown.
 */
export function AdditionalCostsSection() {
	const { tenancyScope, startDate, endDate, productIds } = routeApi.useSearch()
	const { data, isPending, isError } = useGetDashboard({ tenancyScope, startDate, endDate, productIds })

	const view = useMemo(() => {
		if (!data) return null
		if (data.kind === 'MULTI_GLOBAL' || data.kind === 'MULTI_NATIONAL') {
			return { consolidated: true as const }
		}

		const currency = data.store.currency
		const seg = data.stat.costs.segments
		const total = seg.CHARGEBACK.value + seg.REFUND.value + seg.TAXES.value + seg.OPERATIONAL.value

		const rows: CostRow[] = [
			{ key: 'chargeback', icon: CardIcon, label: 'Chargeback', value: formatCurrency(seg.CHARGEBACK.value, currency), valueKind: 'cost', addable: false },
			{ key: 'refund', icon: RefundIcon, label: 'Reembolso', value: formatCurrency(seg.REFUND.value, currency), valueKind: 'cost', addable: false },
			{ key: 'taxes', icon: BalanceIcon, label: 'Impostos', value: formatCurrency(seg.TAXES.value, currency), valueKind: 'cost', addable: true },
			{ key: 'operational', icon: EngineIcon, label: 'Operacional', value: formatCurrency(seg.OPERATIONAL.value, currency), valueKind: 'cost', addable: true },
			{ key: 'warranty', icon: LockIcon, label: 'Garantia', value: 'Sem Garantia', valueKind: 'status', addable: true },
		]

		return { consolidated: false as const, headerTotal: formatCurrency(total, currency), rows }
	}, [data])

	return (
		<Card className="gap-4 p-6">
			<div className="flex items-center gap-4">
				<GradientIconBadge icon={CashIcon} />
				<div className="flex min-w-0 flex-col">
					<span className="text-muted-foreground">Custos Adicionais</span>
					{isPending ? (
						<Skeleton className="mt-1 h-8 w-32" />
					) : (
						<span className="truncate text-3xl font-bold text-foreground">
							{view && !view.consolidated ? view.headerTotal : '—'}
						</span>
					)}
				</div>
			</div>

			<DiscountCostsToggle />

			<div className="border-t border-border/60" />

			<div className="flex flex-col gap-3" role="list" aria-label="Custos adicionais">
				{isPending ? (
					Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-5 w-full" />)
				) : isError || !view ? (
					<p className="text-sm text-muted-foreground">Não foi possível carregar os custos.</p>
				) : view.consolidated ? (
					<p className="text-sm text-muted-foreground">Modo consolidado em breve.</p>
				) : (
					view.rows.map(row => (
						<AdditionalCostRow
							key={row.key}
							icon={row.icon}
							label={row.label}
							value={row.value}
							valueKind={row.valueKind}
							addable={row.addable}
						/>
					))
				)}
			</div>
		</Card>
	)
}

