import { useMemo } from 'react'
import type { ComponentProps } from 'react'
import { getRouteApi } from '@tanstack/react-router'
import { useGetDashboard } from '@bk-dash/client-typescript/typescript'
import type { GetDashboardOutputSINGLEGLOBAL } from '@bk-dash/client-typescript/typescript'

import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { BalanceIcon, CardIcon, CashIcon, EngineIcon, MegaphoneIcon, RefundIcon } from '@/components/ui/icons'
import type { IconComponent } from '@/components/ui/icons'
import { formatCurrency, formatMoneyValue, sumMoney, type MoneyValue } from '@/lib/format'
import { cn } from '@/lib/utils'
import { useTenancyStore } from '@/stores'

import { DiscountCostsToggle } from './DiscountCostsToggle'
import { AdditionalCostRow, type CostTooltipLine } from './AdditionalCostRow'

const routeApi = getRouteApi('/(app)/dashboard/')

type DashboardDetails = GetDashboardOutputSINGLEGLOBAL['details']

// The additional-cost categories rendered as rows, read from `data.details`. Declared as a typed
// subset of the details schema so the row set AND the loading skeleton stay in sync with it.
const COST_KEYS = ['chargeback', 'refund', 'fees', 'taxes', 'ads', 'operational'] as const satisfies readonly (keyof DashboardDetails)[]

const DEFAULT_CURRENCY = 'BRL'

interface CostRowView {
	key: string
	icon: IconComponent
	label: string
	value: string
	tooltip: CostTooltipLine[]
}

/**
 * Additional Costs card — the period's cost categories read from `GetDashboard`'s `details`
 * breakdown, each row revealing its sub-breakdown on hover. Owns the dashboard query for this
 * region and feeds the rows by props. Works in both mono (single-store) and consolidated
 * (multi-store) tenancy: money leaves flow through `MoneyValue`, so consolidated rows show each
 * currency joined by " · ".
 */
export function AdditionalCostsSection({ className, ...props }: ComponentProps<'div'>) {
	const { startDate, endDate, productIds } = routeApi.useSearch()
	const tenancyScope = useTenancyStore(s => s.tenancyScope)
	const { data, isPending, isError } = useGetDashboard({ tenancyScope, startDate, endDate, productIds })

	const view = useMemo(() => {
		if (!data) return null

		// Single-store carries one store currency; consolidated drives currency off the record keys.
		const currency = data.kind === 'SINGLE_GLOBAL' || data.kind === 'SINGLE_NATIONAL' ? data.store.currency : DEFAULT_CURRENCY
		const money = (value: MoneyValue) => formatMoneyValue(value, currency)
		const d = data.details

		const byKey: Record<
			(typeof COST_KEYS)[number],
			{ icon: IconComponent; label: string; total: MoneyValue; tooltip: CostTooltipLine[] }
		> = {
			chargeback: {
				icon: CardIcon,
				label: 'Chargeback',
				total: d.chargeback.byStatus.total.value,
				tooltip: [
					{ label: 'Aberto', value: money(d.chargeback.byStatus.segments.OPEN.value) },
					{ label: 'Perdido', value: money(d.chargeback.byStatus.segments.LOST.value) },
					{ label: 'Ganho', value: money(d.chargeback.byStatus.segments.WON.value) },
					{ label: 'Taxas', value: money(d.chargeback.fees.value) },
				],
			},
			refund: {
				icon: RefundIcon,
				label: 'Reembolso',
				total: d.refund.value,
				tooltip: [{ label: 'Total', value: money(d.refund.value) }],
			},
			fees: {
				icon: CashIcon,
				label: 'Tarifas',
				total: sumMoney([d.fees.gateway.value, d.fees.checkout.value, d.fees.chargeback.value]),
				tooltip: [
					{ label: 'Gateway', value: money(d.fees.gateway.value) },
					{ label: 'Checkout', value: money(d.fees.checkout.value) },
					{ label: 'Chargeback', value: money(d.fees.chargeback.value) },
				],
			},
			taxes: {
				icon: BalanceIcon,
				label: 'Impostos',
				total: sumMoney([d.taxes.ads.value, d.taxes.others.value]),
				tooltip: [
					{ label: 'Anúncios', value: money(d.taxes.ads.value) },
					{ label: 'Outros', value: money(d.taxes.others.value) },
				],
			},
			ads: {
				icon: MegaphoneIcon,
				label: 'Anúncios',
				total: d.ads.total.value,
				tooltip: [
					{ label: 'Meta', value: money(d.ads.byPlatform.segments.META.value) },
					{ label: 'Google', value: money(d.ads.byPlatform.segments.GOOGLE_ADS.value) },
					{ label: 'TikTok', value: money(d.ads.byPlatform.segments.TIKTOK.value) },
					{ label: 'Taboola', value: money(d.ads.byPlatform.segments.TABOOLA.value) },
					{ label: 'Imposto', value: money(d.ads.tax.value) },
				],
			},
			operational: {
				icon: EngineIcon,
				label: 'Operacional',
				total: d.operational.total.value,
				tooltip: d.operational.items.length
					? d.operational.items.map(item => ({ label: item.name, value: formatCurrency(item.amount, item.currency) }))
					: [{ label: 'Sem custos', value: money(0) }],
			},
		}

		const rows: CostRowView[] = COST_KEYS.map(key => {
			const r = byKey[key]
			return { key, icon: r.icon, label: r.label, value: money(r.total), tooltip: r.tooltip }
		})

		const headerTotal = money(sumMoney(COST_KEYS.map(key => byKey[key].total)))
		return { headerTotal, rows }
	}, [data])

	return (
		<Card className={cn('gap-4 p-6', className)} {...props}>
			<div className="flex items-center gap-4">
				<GradientIconBadge icon={CashIcon} />
				<div className="flex min-w-0 flex-col">
					<span className="text-muted-foreground">Custos Adicionais</span>
					{isPending ? (
						<Skeleton className="mt-1 h-8 w-32" />
					) : (
						<span className="truncate text-3xl font-bold text-foreground">{view ? view.headerTotal : '—'}</span>
					)}
				</div>
			</div>

			<DiscountCostsToggle />

			<div className="border-t border-border/60" />

			<div className="flex flex-col gap-3" role="list" aria-label="Custos adicionais">
				{isPending ? (
					COST_KEYS.map(key => <Skeleton key={key} className="h-5 w-full" />)
				) : isError || !view ? (
					<p className="text-sm text-muted-foreground">Não foi possível carregar os custos.</p>
				) : (
					view.rows.map(row => (
						<AdditionalCostRow key={row.key} icon={row.icon} label={row.label} value={row.value} tooltip={row.tooltip} />
					))
				)}
			</div>
		</Card>
	)
}

