			},
			{
				key: 'taxes',
				icon: BalanceIcon,
				label: 'Impostos',
				value: formatCurrency(seg.TAXES.value, currency),
				valueKind: 'cost',
				addable: true,
			},
			{
				key: 'operational',
				icon: EngineIcon,
				label: 'Operacional',
				value: formatCurrency(seg.OPERATIONAL.value, currency),
				valueKind: 'cost',
				addable: true,
			},
			{ key: 'warranty', icon: LockIcon, label: 'Garantia', value: 'Sem Garantia', valueKind: 'status', addable: true },
		]

		return { consolidated: false as const, headerTotal: formatCurrency(total, currency), rows }
	}, [data])

	return (
		<Card className="gap-4 p-6">
			<div className="flex items-center gap-4">
				<GradientIconBadge icon={CashIcon} />
				<div className="flex min-w-0 flex-col gap-2">
					<span className="text-muted-foreground">Custos Adicionais</span>
					{isPending ? (
						<Skeleton className="mt-1 h-8 w-32" />
					) : (
						<span className="truncate text-3xl font-bold text-foreground">{view && !view.consolidated ? view.headerTotal : '—'}</span>
					)}
				</div>
			</div>

			<DiscountCostsToggle />

			<div className="border-t border-border/60" />

			<div className="flex flex-col gap-3" role="list" aria-label="Custos adicionais">
				{isPending ? (
					['chargeback', 'refund', 'taxes', 'operational', 'warranty'].map(key => <Skeleton key={key} className="h-5 w-full" />)
				) : isError || !view ? (
					<p className="text-sm text-muted-foreground">Não foi possível carregar os custos.</p>
				) : view.consolidated ? (
					<p className="text-sm text-muted-foreground">Modo consolidado em breve.</p>
				) : (
					view.rows.map(row => (
						<AdditionalCostRow
							key={row.key}
							icon={row.icon}
							label={row.label}
							value={row.value}
							valueKind={row.valueKind}
							addable={row.addable}
						/>
					))
				)}
			</div>
		</Card>
	)
}

