export const dashboardSearchSchema = z.object({
	startDate: z.string().default(() => startOfDay(subDays(new Date(), 29)).toISOString()),
	endDate: z.string().default(() => endOfDay(new Date()).toISOString()),
	productIds: z.array(z.string()).optional(),
})

export const Route = createFileRoute('/(app)/dashboard/')({
	validateSearch: search => dashboardSearchSchema.parse(search ?? {}),
	component: RouteComponent,
})

// Mock route shell — the real screen (incl. the Additional Costs card) is showcased in Storybook
