import { useMemo } from 'react'
import type { ComponentProps } from 'react'
import { useTranslation } from 'react-i18next'
import { getRouteApi } from '@tanstack/react-router'
import { useGetDashboard } from '@bk-dash/client-typescript/typescript'
import type { GetDashboard200 } from '@bk-dash/client-typescript/typescript'

import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { BalanceIcon, CardIcon, CashIcon, EngineIcon, MegaphoneIcon, RefundIcon } from '@/components/ui/icons'
import type { IconComponent } from '@/components/ui/icons'
import { formatCurrency, formatMoneyValue, sumMoney, type MoneyValue } from '@/lib/format'
import { cn } from '@/lib/utils'
import { useTenancyStore } from '@/stores'

import { DiscountCostsToggle } from './DiscountCostsToggle'
import { AdditionalCostRow, type CostTooltipLine } from './AdditionalCostRow'

const routeApi = getRouteApi('/(app)/dashboard/')

type DashboardDetails = GetDashboard200['details']

// The additional-cost categories rendered as rows, read from `data.details`. Declared as a typed
// subset of the details schema so the row set AND the loading skeleton stay in sync with it.
const COST_KEYS = ['chargeback', 'refund', 'fees', 'taxes', 'ads', 'operational'] as const satisfies readonly (keyof DashboardDetails)[]

const DEFAULT_CURRENCY = 'BRL'

interface CostRowView {
	key: string
	icon: IconComponent
	label: string
	value: string
	tooltip: CostTooltipLine[]
}

/**
 * Additional Costs card — the period's cost categories read from `GetDashboard`'s `details`
 * breakdown, each row revealing its sub-breakdown on hover. Owns the dashboard query for this
 * region and feeds the rows by props. Works in both mono (single-store) and consolidated
 * (multi-store) tenancy: money leaves flow through `MoneyValue`, so consolidated rows show each
 * currency joined by " · ". All copy is i18n-driven; currency formatting follows the active locale.
 */
export function AdditionalCostsSection({ className, ...props }: ComponentProps<'div'>) {
	const { t, i18n } = useTranslation()
	const locale = i18n.language?.startsWith('en') ? 'en-US' : 'pt-BR'
	const { startDate, endDate, productIds } = routeApi.useSearch()
	const tenancyScope = useTenancyStore(s => s.tenancyScope)
	const { data, isPending, isError } = useGetDashboard({ tenancyScope, startDate, endDate, productIds })

	const view = useMemo(() => {
		if (!data) return null

		const tc = (key: string) => t(`dashboard.additionalCosts.${key}`)
		// Single-store carries one store currency; consolidated drives currency off the record keys.
		const currency = data.kind === 'SINGLE_GLOBAL' || data.kind === 'SINGLE_NATIONAL' ? data.store.currency : DEFAULT_CURRENCY
		const money = (value: MoneyValue) => formatMoneyValue(value, currency, locale)
		const d = data.details

		const byKey: Record<
			(typeof COST_KEYS)[number],
			{ icon: IconComponent; label: string; total: MoneyValue; tooltip: CostTooltipLine[] }
		> = {
			chargeback: {
				icon: CardIcon,
				label: tc('rows.chargeback'),
				total: d.chargeback.byStatus.total.value,
				tooltip: [
					{ label: tc('tooltip.open'), value: money(d.chargeback.byStatus.segments.OPEN.value) },
					{ label: tc('tooltip.lost'), value: money(d.chargeback.byStatus.segments.LOST.value) },
					{ label: tc('tooltip.won'), value: money(d.chargeback.byStatus.segments.WON.value) },
					{ label: tc('tooltip.fees'), value: money(d.chargeback.fees.value) },
				],
			},
			refund: {
				icon: RefundIcon,
				label: tc('rows.refund'),
				total: d.refund.value,
				tooltip: [{ label: tc('tooltip.total'), value: money(d.refund.value) }],
			},
			fees: {
				icon: CashIcon,
				label: tc('rows.fees'),
				total: sumMoney([d.fees.gateway.value, d.fees.checkout.value, d.fees.chargeback.value]),
				tooltip: [
					{ label: tc('tooltip.gateway'), value: money(d.fees.gateway.value) },
					{ label: tc('tooltip.checkout'), value: money(d.fees.checkout.value) },
					{ label: tc('tooltip.chargeback'), value: money(d.fees.chargeback.value) },
				],
			},
			taxes: {
				icon: BalanceIcon,
				label: tc('rows.taxes'),
				total: sumMoney([d.taxes.ads.value, d.taxes.others.value]),
				tooltip: [
					{ label: tc('tooltip.ads'), value: money(d.taxes.ads.value) },
					{ label: tc('tooltip.others'), value: money(d.taxes.others.value) },
				],
			},
			ads: {
				icon: MegaphoneIcon,
				label: tc('rows.ads'),
				total: d.ads.total.value,
				tooltip: [
					{ label: tc('tooltip.meta'), value: money(d.ads.byPlatform.segments.META.value) },
					{ label: tc('tooltip.google'), value: money(d.ads.byPlatform.segments.GOOGLE_ADS.value) },
					{ label: tc('tooltip.tiktok'), value: money(d.ads.byPlatform.segments.TIKTOK.value) },
