import { describe, it, expect } from 'bun:test'
import { TenancyScope, DashboardMode } from '@bk-dash/contracts-typescript/wire/enums'
import { GetDashboard, GetDashboardOutputSchema } from './GetDashboard'
import { MockStoreVisualizationRepository } from '../repositories/StoreVisualizationRepository/MockStoreVisualizationRepository'
import { StoreVisualization } from '../entities/StoreVisualization'

const STORE_ID = '11111111-1111-4111-8111-111111111111'
const STORE_IDS = ['11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222']
const RANGE = { startDate: new Date('2026-05-01T00:00:00Z'), endDate: new Date('2026-05-31T00:00:00Z') }

function makeUseCase(persistedMode?: DashboardMode): GetDashboard {
	const repo = new MockStoreVisualizationRepository()
	if (persistedMode) repo.seed(StoreVisualization.create({ storeId: STORE_ID, dashboardMode: persistedMode }))
	return new GetDashboard(repo)
}

function run(tenancyScope: TenancyScope, persistedMode?: DashboardMode) {
