		const out = await run(TenancyScope.SINGLE_STORE, DashboardMode.NATIONAL)
		expect(out.kind).toBe('SINGLE_NATIONAL')
		expect(out.dashboardMode).toBe(DashboardMode.NATIONAL)
		expect('paymentMethods' in out).toBe(true)
	})

	it('MULTI + default → MULTI_GLOBAL: perStore (keyed by storeIds) + no store, no paymentMethods', async () => {
		const out = await run(TenancyScope.MULTI_STORE)
		expect(out.kind).toBe('MULTI_GLOBAL')
		expect('perStore' in out).toBe(true)
		expect('store' in out).toBe(false)
		expect('paymentMethods' in out).toBe(false)
		expect(Object.keys((out as { perStore: Record<string, unknown> }).perStore).sort()).toEqual([...STORE_IDS].sort())
	})

	it('MULTI + persisted NATIONAL → MULTI_NATIONAL: perStore + paymentMethods', async () => {
		const out = await run(TenancyScope.MULTI_STORE, DashboardMode.NATIONAL)
		expect(out.kind).toBe('MULTI_NATIONAL')
		expect('perStore' in out).toBe(true)
