 * Additional Costs card — the period's cost categories read from `GetDashboard`'s `details`
 * breakdown, each row revealing its sub-breakdown on hover. Owns the dashboard query for this
 * region and feeds the rows by props. Works in both mono (single-store) and consolidated
 * (multi-store) tenancy: money leaves flow through `MoneyValue`, so consolidated rows show each
 * currency joined by " · ". All copy is i18n-driven; currency formatting follows the active locale.
 */
export function AdditionalCostsSection({ className, ...props }: ComponentProps<'div'>) {
	const { t, i18n } = useTranslation()
	const locale = i18n.language?.startsWith('en') ? 'en-US' : 'pt-BR'
	const { startDate, endDate, productIds } = routeApi.useSearch()
	const tenancyScope = useTenancyStore(s => s.tenancyScope)
	const { data, isPending, isError } = useGetDashboard({ tenancyScope, startDate, endDate, productIds })

	const view = useMemo(() => {
		if (!data) return null

		// Single-store carries one store currency; consolidated drives currency off the record keys.
		const currency = data.kind === 'SINGLE_GLOBAL' || data.kind === 'SINGLE_NATIONAL' ? data.store.currency : DEFAULT_CURRENCY
		const money = (value: MoneyValue) => formatMoneyValue(value, currency, locale)
		const d = data.details

		const byKey: Record<(typeof COST_KEYS)[number], { icon: IconComponent; label: string; total: MoneyValue; tooltip: CostTooltipLine[] }> =
			{
				chargeback: {
					icon: CardIcon,
					label: t('dashboard.additionalCosts.rows.chargeback'),
					total: d.chargeback.byStatus.total.value,
					tooltip: [
						{ label: t('dashboard.additionalCosts.tooltip.open'), value: money(d.chargeback.byStatus.segments.OPEN.value) },
						{ label: t('dashboard.additionalCosts.tooltip.lost'), value: money(d.chargeback.byStatus.segments.LOST.value) },
						{ label: t('dashboard.additionalCosts.tooltip.won'), value: money(d.chargeback.byStatus.segments.WON.value) },
						{ label: t('dashboard.additionalCosts.tooltip.fees'), value: money(d.chargeback.fees.value) },
					],
				},
				refund: {
					icon: RefundIcon,
					label: t('dashboard.additionalCosts.rows.refund'),
					total: d.refund.value,
					tooltip: [{ label: t('dashboard.additionalCosts.tooltip.total'), value: money(d.refund.value) }],
				},
				fees: {
					icon: CashIcon,
					label: t('dashboard.additionalCosts.rows.fees'),
					total: sumMoney([d.fees.gateway.value, d.fees.checkout.value, d.fees.chargeback.value]),
					tooltip: [
						{ label: t('dashboard.additionalCosts.tooltip.gateway'), value: money(d.fees.gateway.value) },
						{ label: t('dashboard.additionalCosts.tooltip.checkout'), value: money(d.fees.checkout.value) },
						{ label: t('dashboard.additionalCosts.tooltip.chargeback'), value: money(d.fees.chargeback.value) },
					],
				},
				taxes: {
					icon: BalanceIcon,
					label: t('dashboard.additionalCosts.rows.taxes'),
					total: sumMoney([d.taxes.ads.value, d.taxes.others.value]),
					tooltip: [
						{ label: t('dashboard.additionalCosts.tooltip.ads'), value: money(d.taxes.ads.value) },
						{ label: t('dashboard.additionalCosts.tooltip.others'), value: money(d.taxes.others.value) },
					],
				},
				ads: {
					icon: MegaphoneIcon,
					label: t('dashboard.additionalCosts.rows.ads'),
					total: d.ads.total.value,
					tooltip: [
						{ label: t('dashboard.additionalCosts.tooltip.meta'), value: money(d.ads.byPlatform.segments.META.value) },
						{ label: t('dashboard.additionalCosts.tooltip.google'), value: money(d.ads.byPlatform.segments.GOOGLE_ADS.value) },
						{ label: t('dashboard.additionalCosts.tooltip.tiktok'), value: money(d.ads.byPlatform.segments.TIKTOK.value) },
						{ label: t('dashboard.additionalCosts.tooltip.taboola'), value: money(d.ads.byPlatform.segments.TABOOLA.value) },
						{ label: t('dashboard.additionalCosts.tooltip.tax'), value: money(d.ads.tax.value) },
					],
				},
				operational: {
					icon: EngineIcon,
					label: t('dashboard.additionalCosts.rows.operational'),
					total: d.operational.total.value,
					tooltip: d.operational.items.length
						? d.operational.items.map(item => ({ label: item.name, value: formatCurrency(item.amount, item.currency, locale) }))
						: [{ label: t('dashboard.additionalCosts.tooltip.noCosts'), value: money(0) }],
				},
			}

		const rows: CostRowView[] = COST_KEYS.map(key => {
			const r = byKey[key]
			return { key, icon: r.icon, label: r.label, value: money(r.total), tooltip: r.tooltip }
		})

		const headerTotal = money(sumMoney(COST_KEYS.map(key => byKey[key].total)))
		return { headerTotal, rows }
	}, [data, t, locale])

	return (
		<Card className={cn('gap-4 p-6', className)} {...props}>
			<div className="flex items-center gap-4">
				<GradientIconBadge icon={CashIcon} />
				<div className="flex min-w-0 flex-col">
					<span className="text-muted-foreground">{t('dashboard.additionalCosts.title')}</span>
					{isPending ? (
						<Skeleton className="mt-1 h-8 w-32" />
					) : (
						<span className="truncate text-3xl font-bold text-foreground">{view ? view.headerTotal : '—'}</span>
					)}
				</div>
			</div>

			<DiscountCostsToggle />

			<div className="border-t border-border/60" />

			<div className="flex flex-col gap-3" role="list" aria-label={t('dashboard.additionalCosts.listAria')}>
				{isPending ? (
					COST_KEYS.map(key => <Skeleton key={key} className="h-5 w-full" />)
				) : isError || !view ? (
					<p className="text-sm text-muted-foreground">{t('dashboard.additionalCosts.loadError')}</p>
				) : (
					view.rows.map(row => (
						<AdditionalCostRow key={row.key} icon={row.icon} label={row.label} value={row.value} tooltip={row.tooltip} />
					))
				)}
			</div>
		</Card>
	)
}

