import { useId } from 'react'
import type { ComponentProps, ComponentType, CSSProperties, ReactNode } from 'react'

import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import type { IconComponent } from '@/components/ui/icons'
import { cn } from '@/lib/utils'

export interface CostTooltipLine {
	label: string
	value: string
}

/**
 * Paints a fill-based icon with the app's vertical gradient. The shared GradientIcon sets `fill` on
 * the `<svg>`, which the icons' own per-path `fill="currentColor"` overrides (so it renders flat).
 * Here the gradient is forced onto the paths via a CSS rule — a CSS declaration beats the path's
 * presentation attribute. Gradient color follows the element's text color (currentColor).
 */
function GradientCostIcon({ icon: Icon }: { icon: IconComponent }) {
	const id = `cost-gi-${useId().replace(/:/g, '')}`
	const Svg = Icon as ComponentType<{ className?: string; style?: CSSProperties }>
	return (
		<span className="relative inline-flex size-4 shrink-0 items-center justify-center text-muted-foreground">
			<svg width="0" height="0" className="absolute" aria-hidden>
				<defs>
					<linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
						<stop offset="0%" stopColor="currentColor" stopOpacity={1} />
						<stop offset="100%" stopColor="currentColor" stopOpacity={0.45} />
					</linearGradient>
				</defs>
			</svg>
			<Svg className="size-4 [&_path]:fill-[var(--cost-gi)]" style={{ '--cost-gi': `url(#${id})` } as CSSProperties} />
		</span>
	)
}

/** Standard breakdown tooltip: left-aligned `label: value` lines. */
export function CostTooltipLines({ lines }: { lines: CostTooltipLine[] }) {
	return (
		<div className="flex flex-col gap-1">
			{lines.map(line => (
				<div key={line.label} className="flex gap-2">
					<span className="text-muted-foreground">{line.label}:</span>
					<span className="font-medium text-foreground">{line.value}</span>
				</div>
			))}
		</div>
	)
}

